//go:build ignore

// Synthetic plugin runner, no network or real CLI invocation. Exercises actual replay orchestration/settings writes.
package main
import("context";"fmt";"os";"path/filepath";"strings";"amagi-codebox/internal/platform";w "amagi-codebox/internal/wslsupply")
func must(e error){if e!=nil{panic(e)}}
func main(){root,e:=os.MkdirTemp("","review-filters-");must(e);defer os.RemoveAll(root);agent:=filepath.Join(root,"target/home/u/.pi/agent");p:=w.Probes{Identity:func(string)platform.WSLUserIdentity{return platform.WSLUserIdentity{UID:"1000",Home:"/home/u",MachineID:"fixture",OK:true}},ToUNC:func(_,p string)string{return filepath.Join(root,"target",filepath.FromSlash(strings.TrimPrefix(p,"/")))},Chmod:func(string,string,...string)error{return nil}};c:=w.NewCoordinator(filepath.Join(root,"state"),nil,p);c.SetPluginSourceParser(func(raw string)w.PluginSourceSpec{return w.PluginSourceSpec{Type:"npm",Name:"demo",Ref:"1.0.0"}},w.PluginRefChecker{ExactNpmVersion:func(string)bool{return true}});c.SetPluginCommandRunner(func(_ context.Context,_,cmd string)(string,error){if strings.Contains(cmd,"command -v pi"){return "/usr/bin/pi",nil};if strings.HasPrefix(cmd,"pi install "){must(os.MkdirAll(filepath.Join(agent,"npm/node_modules/demo"),0700));must(os.WriteFile(filepath.Join(agent,"npm/node_modules/demo/package.json"),[]byte(`{"version":"1.0.0"}`),0600));must(os.WriteFile(filepath.Join(agent,"settings.json"),[]byte(`{"packages":["npm:demo@1.0.0"]}`),0600));return "",nil};return "",fmt.Errorf("unexpected fixture command: %s",cmd)});first:=c.RunPluginOperation(context.Background(),"A",w.PluginOperation{Source:"npm:demo@1.0.0",Kind:w.PluginOpInstall,AnchorRef:"1.0.0",Filters:w.PluginFilters{Skills:[]string{}}});next:=c.RunPluginOperation(context.Background(),"A",w.PluginOperation{Source:"npm:demo@1.0.0",Kind:w.PluginOpUpdate,AnchorRef:"1.0.0",Filters:w.PluginFilters{}});b,e:=os.ReadFile(filepath.Join(agent,"settings.json"));must(e);fmt.Printf("CLEAR_FILTERS first=%s update=%s ok=%v settings=%s\n",first.Outcome,next.Outcome,next.OK,b)}
